CREATE TABLE customer_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), status text NOT NULL DEFAULT 'active', ciphertext bytea NOT NULL, iv bytea NOT NULL, auth_tag bytea NOT NULL, key_id text NOT NULL, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_profile_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_profile_id uuid NOT NULL REFERENCES customer_profiles(id), user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_profile_id, user_id));
CREATE TABLE customer_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ciphertext bytea NOT NULL, iv bytea NOT NULL, auth_tag bytea NOT NULL, key_id text NOT NULL, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_profile_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_profile_id uuid NOT NULL REFERENCES customer_profiles(id), customer_address_id uuid NOT NULL REFERENCES customer_addresses(id), label text, deactivated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_profile_id, customer_address_id));
CREATE INDEX customer_profile_memberships_user_id_idx ON customer_profile_memberships (user_id);
CREATE INDEX customer_profile_addresses_profile_id_idx ON customer_profile_addresses (customer_profile_id) WHERE deactivated_at IS NULL;
